CREATE TABLE public.ministry_history_lines (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  label text NOT NULL CHECK (btrim(label) <> '')
);

CREATE UNIQUE INDEX ministry_history_lines_label_key
  ON public.ministry_history_lines (lower(btrim(label)));

CREATE TABLE public.ministry_history_entries (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  kind text NOT NULL CHECK (kind IN ('phase', 'term')),
  line_id text REFERENCES public.ministry_history_lines (id),
  name text NOT NULL CHECK (btrim(name) <> ''),
  starts_on date NOT NULL,
  ends_on date CHECK (ends_on >= starts_on),
  party text,
  office text,
  note text,
  citation text NOT NULL CHECK (btrim(citation) <> ''),
  source_detail text,
  source_url text CHECK (source_url ~* '^https?://[^[:space:]]+$'),
  source_verified boolean NOT NULL DEFAULT false,
  assignment_confirmed boolean NOT NULL DEFAULT false,
  revision integer NOT NULL DEFAULT 1,
  CHECK (NOT assignment_confirmed OR line_id IS NOT NULL)
);

CREATE INDEX ministry_history_entries_line_dates_idx
  ON public.ministry_history_entries (line_id, starts_on);

CREATE TABLE public.ministry_history_links (
  predecessor_id text NOT NULL REFERENCES public.ministry_history_lines (id),
  successor_id text NOT NULL REFERENCES public.ministry_history_lines (id),
  effective_on date NOT NULL,
  note text NOT NULL CHECK (btrim(note) <> ''),
  PRIMARY KEY (predecessor_id, successor_id, effective_on),
  CHECK (predecessor_id <> successor_id)
);

CREATE TABLE public.ministry_history_changes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  entry_id text NOT NULL REFERENCES public.ministry_history_entries (id),
  revision integer NOT NULL,
  changed_at timestamptz NOT NULL DEFAULT now(),
  changed_by uuid DEFAULT auth.uid(),
  before_data jsonb,
  after_data jsonb NOT NULL,
  UNIQUE (entry_id, revision)
);

-- Versionsstand der bisher ausgelieferten Ministerien-Historie. Die ursprünglichen IDs bleiben erhalten.


ALTER TABLE public.ministry_history_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ministry_history_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ministry_history_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ministry_history_changes ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.ministry_history_lines, public.ministry_history_entries,
  public.ministry_history_links, public.ministry_history_changes FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON public.ministry_history_lines TO authenticated;
GRANT SELECT, INSERT ON public.ministry_history_entries TO authenticated;
GRANT UPDATE (line_id, name, starts_on, ends_on, party, office, note, citation, source_detail,
  source_url, source_verified, assignment_confirmed) ON public.ministry_history_entries TO authenticated;
GRANT SELECT, INSERT ON public.ministry_history_links TO authenticated;
GRANT SELECT ON public.ministry_history_changes TO authenticated;

CREATE POLICY ministry_history_lines_select ON public.ministry_history_lines
  FOR SELECT TO authenticated USING ((SELECT public.is_superadmin(auth.uid())));
CREATE POLICY ministry_history_lines_insert ON public.ministry_history_lines
  FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_superadmin(auth.uid())));
CREATE POLICY ministry_history_entries_select ON public.ministry_history_entries
  FOR SELECT TO authenticated USING ((SELECT public.is_superadmin(auth.uid())));
CREATE POLICY ministry_history_entries_insert ON public.ministry_history_entries
  FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_superadmin(auth.uid())) AND revision = 1);
CREATE POLICY ministry_history_entries_update ON public.ministry_history_entries
  FOR UPDATE TO authenticated USING ((SELECT public.is_superadmin(auth.uid())))
  WITH CHECK ((SELECT public.is_superadmin(auth.uid())));
CREATE POLICY ministry_history_links_select ON public.ministry_history_links
  FOR SELECT TO authenticated USING ((SELECT public.is_superadmin(auth.uid())));
CREATE POLICY ministry_history_links_insert ON public.ministry_history_links
  FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_superadmin(auth.uid())));
CREATE POLICY ministry_history_changes_select ON public.ministry_history_changes
  FOR SELECT TO authenticated USING ((SELECT public.is_superadmin(auth.uid())));

CREATE FUNCTION public.trg_bump_ministry_history_revision()
RETURNS trigger LANGUAGE plpgsql SET search_path = ''
AS $$
BEGIN
  NEW.revision := OLD.revision + 1;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.trg_record_ministry_history_change()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $$
BEGIN
  VALUES (NEW.id, NEW.revision, CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END, to_jsonb(NEW));
  RETURN NULL;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.trg_bump_ministry_history_revision() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.trg_record_ministry_history_change() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER ministry_history_entry_revision BEFORE UPDATE ON public.ministry_history_entries
  FOR EACH ROW EXECUTE FUNCTION public.trg_bump_ministry_history_revision();
CREATE TRIGGER ministry_history_entry_audit AFTER INSERT OR UPDATE ON public.ministry_history_entries
  FOR EACH ROW EXECUTE FUNCTION public.trg_record_ministry_history_change();

CREATE FUNCTION public.confirm_ministry_history_assignments(expected_entries jsonb)
RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path = ''
AS $$
DECLARE
  confirmed integer;
BEGIN
  IF public.is_superadmin(auth.uid()) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Super-Admin erforderlich' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ministry_history_entries AS entry
  SET assignment_confirmed = true
  FROM jsonb_to_recordset(expected_entries) AS expected(id text, revision integer)
  WHERE entry.id = expected.id AND entry.revision = expected.revision
    AND entry.line_id IS NOT NULL AND NOT entry.assignment_confirmed;
  GET DIAGNOSTICS confirmed = ROW_COUNT;
  IF confirmed <> jsonb_array_length(expected_entries) THEN
    RAISE EXCEPTION 'Einträge wurden inzwischen geändert. Bitte neu laden.' USING ERRCODE = 'PT409';
  END IF;
  RETURN confirmed;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.confirm_ministry_history_assignments(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.confirm_ministry_history_assignments(jsonb) TO authenticated;
